// Generated by `tsir make:link-client`. Verifies the client can be constructed
// with a base URL and host allowlist, and that `get` returns a call result.
import { describe, expect, test } from 'bun:test';

import { AnalyticsClient } from './analytics.client.ts';

describe('AnalyticsClient', () => {
  test('constructs with base URL and allowlist', () => {
    const client = new AnalyticsClient({
      baseUrl: 'https://analytics.local',
      allowedHosts: ['analytics.local'],
    });
    expect(client).toBeInstanceOf(AnalyticsClient);
  });

  test('refuses a host not in the allowlist', () => {
    expect(
      () =>
        new AnalyticsClient({
          baseUrl: 'https://evil.test',
          allowedHosts: ['analytics.local'],
        }),
    ).toThrow();
  });
});
